python3 - <<'PY'
import json
import os

needs = json.loads(os.environ["NEEDS_JSON"])
# A leaf short-circuit-skipped by diff scoping (not selected for
# this diff) reports "skipped" -- not blocking. A genuinely failed
# or cancelled leaf is.
blocking = {
    job: result.get("result")
    for job, result in needs.items()
    if result.get("result") in {"failure", "cancelled"}
}
if blocking:
    raise SystemExit(f"blocking job(s) did not succeed: {blocking}")
print(f"modules-gate OK (mode={os.environ['MODE']})")
PY

python3 - <<'PY'
import json
import os

needs = json.loads(os.environ["NEEDS_JSON"])
expected = {
    "lint",
    "build-wheel",
    "clean-install-verification",
    "uv-lock-check",
}
if set(needs) != expected:
    raise SystemExit(f"quality-gate needs changed: {sorted(needs)}")
failed = {
    job: result.get("result")
    for job, result in needs.items()
    if result.get("result") != "success"
}
if failed:
    raise SystemExit(f"blocking job(s) did not succeed: {failed}")
PY

with.script:
// This workflow is schedule/dispatch-only (never workflow_run), so
// it has no "triggering run" to key off like ci-aggregate.yml does
// -- it resolves its own current + fallback runs by branch, newest
// first (the cross-workflow generalization of ci-aggregate.yml's
// same-run-triggered current/fallback pattern).
const branch = context.ref.replace('refs/heads/', '');
const { data } = await github.rest.actions.listWorkflowRuns({
  owner: context.repo.owner,
  repo: context.repo.repo,
  workflow_id: 'ci-modules.yml',
  branch,
  status: 'success',
  per_page: 5,
});
const runs = data.workflow_runs;
const runId = runs[0] ? String(runs[0].id) : '';
const fallbackRunId = runs[1] ? String(runs[1].id) : '';
core.setOutput('run_id', runId);
core.setOutput('fallback_run_id', fallbackRunId);
if (runId) {
  console.log(`sonar: current CI Modules run=${runId}${fallbackRunId ? `, fallback run=${fallbackRunId}` : ' (no fallback run found)'}`);
} else {
  console.log('sonar: no successful "CI Modules" run found for this branch -- scan will run with zero coverage report paths.');
}
